package repository;

import model.ClosedTab;
import model.Item;
import model.Tab;
import model.Table;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.List;

public class TabRepository {
    private final Database database;

    public TabRepository(Database database) {
        this.database = database;
    }

    // Creates a new open tab and returns it with the id generated by the database
    public Tab insert(String label, Table table) {
        String sql = "INSERT INTO tab (label, table_side) VALUES (?, ?)";
        try (Connection connection = database.connect();
             PreparedStatement statement = connection.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
            statement.setString(1, label);
            statement.setString(2, table.name());
            statement.executeUpdate();
            try (ResultSet keys = statement.getGeneratedKeys()) {
                keys.next();
                return new Tab(keys.getInt(1), label, table);
            }
        } catch (SQLException e) {
            throw dbError(e);
        }
    }

    // Saves the current state of a tab (note + all items) in a single transaction
    public void save(Tab tab) {
        try (Connection connection = database.connect()) {
            connection.setAutoCommit(false);
            try {
                try (PreparedStatement update = connection.prepareStatement("UPDATE tab SET note = ? WHERE id = ?")) {
                    update.setString(1, tab.getNote());
                    update.setInt(2, tab.getId());
                    update.executeUpdate();
                }
                try (PreparedStatement delete = connection.prepareStatement("DELETE FROM tab_item WHERE tab_id = ?")) {
                    delete.setInt(1, tab.getId());
                    delete.executeUpdate();
                }
                String insertSql = "INSERT INTO tab_item (tab_id, name, price, quantity) VALUES (?, ?, ?, ?)";
                try (PreparedStatement insert = connection.prepareStatement(insertSql)) {
                    for (Item item : tab.getItems()) {
                        insert.setInt(1, tab.getId());
                        insert.setString(2, item.getName());
                        insert.setDouble(3, item.getPrice());
                        insert.setInt(4, item.getQuantity());
                        insert.executeUpdate();
                    }
                }
                connection.commit();
            } catch (SQLException e) {
                connection.rollback();
                throw e;
            }
        } catch (SQLException e) {
            throw dbError(e);
        }
    }

    // Closing keeps the tab and its items in the database (history), it only changes the status
    public void close(int tabId) {
        String sql = "UPDATE tab SET status = 'CLOSED', closed_at = datetime('now', 'localtime') "
                + "WHERE id = ? AND status = 'OPEN'";
        try (Connection connection = database.connect();
             PreparedStatement statement = connection.prepareStatement(sql)) {
            statement.setInt(1, tabId);
            statement.executeUpdate();
        } catch (SQLException e) {
            throw dbError(e);
        }
    }

    public List<Tab> findOpen() {
        List<Tab> tabs = new ArrayList<>();
        String tabsSql = "SELECT id, label, table_side, note FROM tab WHERE status = 'OPEN' ORDER BY id";
        String itemsSql = "SELECT name, price, quantity FROM tab_item WHERE tab_id = ? ORDER BY id";
        try (Connection connection = database.connect();
             PreparedStatement tabStatement = connection.prepareStatement(tabsSql);
             ResultSet tabRows = tabStatement.executeQuery()) {
            while (tabRows.next()) {
                Tab tab = new Tab(tabRows.getInt("id"), tabRows.getString("label"),
                        Table.valueOf(tabRows.getString("table_side")));
                tab.setNote(tabRows.getString("note"));
                try (PreparedStatement itemStatement = connection.prepareStatement(itemsSql)) {
                    itemStatement.setInt(1, tab.getId());
                    try (ResultSet itemRows = itemStatement.executeQuery()) {
                        while (itemRows.next()) {
                            tab.addItem(itemRows.getString("name"), itemRows.getDouble("price"),
                                    itemRows.getInt("quantity"));
                        }
                    }
                }
                tabs.add(tab);
            }
        } catch (SQLException e) {
            throw dbError(e);
        }
        return tabs;
    }

    // Most recently closed tabs first
    public List<ClosedTab> findClosed(int limit) {
        List<ClosedTab> closed = new ArrayList<>();
        String tabsSql = "SELECT id, label, table_side, note, opened_at, closed_at FROM tab "
                + "WHERE status = 'CLOSED' ORDER BY closed_at DESC, id DESC LIMIT ?";
        String itemsSql = "SELECT name, price, quantity FROM tab_item WHERE tab_id = ? ORDER BY id";
        try (Connection connection = database.connect();
             PreparedStatement tabStatement = connection.prepareStatement(tabsSql)) {
            tabStatement.setInt(1, limit);
            try (ResultSet tabRows = tabStatement.executeQuery()) {
                while (tabRows.next()) {
                    int id = tabRows.getInt("id");
                    List<Item> items = new ArrayList<>();
                    try (PreparedStatement itemStatement = connection.prepareStatement(itemsSql)) {
                        itemStatement.setInt(1, id);
                        try (ResultSet itemRows = itemStatement.executeQuery()) {
                            while (itemRows.next()) {
                                items.add(new Item(itemRows.getString("name"), itemRows.getDouble("price"),
                                        itemRows.getInt("quantity")));
                            }
                        }
                    }
                    closed.add(new ClosedTab(id, tabRows.getString("label"),
                            Table.valueOf(tabRows.getString("table_side")), tabRows.getString("note"),
                            tabRows.getString("opened_at"), tabRows.getString("closed_at"), items));
                }
            }
        } catch (SQLException e) {
            throw dbError(e);
        }
        return closed;
    }

    private IllegalStateException dbError(SQLException e) {
        return new IllegalStateException("Erro no banco de dados: " + e.getMessage(), e);
    }
}
